-- ===========================================================================
-- paquete's Hyprland config — single file
-- ===========================================================================
-- Loaded natively by Hyprland 0.56+ (this file replaces hyprland.conf).
-- Sections appear in load order; each maps 1:1 to a file from the old
-- multi-file layout (noted in each banner). The only external file is
-- noctalia.lua, which is regenerated by Noctalia — do not hand-edit it.
-- Switching user = `git checkout user/ecila` (each user has a branch).
-- Rollback to the old multi-file layout = `git checkout main`.
-- If this file ever feels too big, split sections into files for THIS user
-- only — there is no dynamic per-user dispatcher anymore.
-- ===========================================================================

-- ===== PERMISSIONS (was: users/paquete/init.lua) =====
hl.permission({
    binary = "/usr/(bin|local/bin)/hyprpm",
    type   = "plugin",
    mode   = "allow",
})

-- ===== CURSOR WARP HELPER (was: lib/warp.lua) =====
-- Warps the cursor to the focused monitor's center if it isn't already there,
-- so monitor-switching keybinds feel natural without warping on every mouse move.
local function warp_if_monitor_changed()
    local mon = hl.get_active_monitor()
    if not mon then return end
    local pos = hl.get_cursor_pos()
    if not pos then return end
    local mw = mon.width / mon.scale
    local mh = mon.height / mon.scale
    if pos.x >= mon.x and pos.x < mon.x + mw and pos.y >= mon.y and pos.y < mon.y + mh then
        return
    end
    hl.dispatch(hl.dsp.cursor.move({ x = mon.x + mw / 2, y = mon.y + mh / 2 }))
end

